    Wait tryWait(int thread) { return Wait::Acquired; }
    bool release(int thread) { return true; }
    void threadEnded(int thread) {}
    std::optional<int> owner() const { return std::nullopt; }
};

class Semaphore
{
public:
    Semaphore(int initial, int maximum) {}
    bool tryWait() { return true; }
    bool release(int count) { return true; }
    int count() const { return 0; }
};

solution.solution.cpp:
#include <optional>

enum class Wait { Acquired, Abandoned, Timeout };

class Mutex
{
public:
    Wait tryWait(int thread)
    {
        if (holder && *holder != thread) return Wait::Timeout;
        if (holder) { ++depth; return Wait::Acquired; }
        holder = thread;
        depth = 1;
        if (abandoned) { abandoned = false; return Wait::Abandoned; }
        return Wait::Acquired;
    }

    bool release(int thread)
    {
        if (!holder || *holder != thread) return false;
        if (--depth == 0) holder.reset();
        return true;
    }

    void threadEnded(int thread)
    {
        if (holder && *holder == thread) { holder.reset(); depth = 0; abandoned = true; }
    }

    std::optional<int> owner() const { return holder; }

private:
    std::optional<int> holder;
    int depth{ 0 };
    bool abandoned{ false };
};

class Semaphore
{
public:
    Semaphore(int initial, int maximum) : value{ initial }, maximum{ maximum } {}

    bool tryWait()
    {
        if (value == 0) return false;
        --value;
        return true;
    }

    bool release(int count)
    {
        if (count <= 0 || value + count > maximum) return false;
        value += count;
        return true;
    }

    int count() const { return value; }

private:
    int value;
    int maximum;
};

unitTests:
TEST("ownership and recursion") {
    Mutex m;
    CHECK(m.tryWait(1) == Wait::Acquired);
    CHECK(m.tryWait(2) == Wait::Timeout);
    CHECK(m.tryWait(1) == Wait::Acquired);
    CHECK(m.release(1));
    CHECK_EQ(m.owner().value_or(0), 1);
    CHECK(!m.release(2));
    CHECK(m.release(1));
    CHECK(!m.owner().has_value());
    CHECK(!m.release(1));
    CHECK(m.tryWait(2) == Wait::Acquired);
}
TEST("abandoned when the owner dies") {
    Mutex m;
    m.tryWait(7);
    m.threadEnded(8);
    CHECK_EQ(m.owner().value_or(0), 7);
    m.threadEnded(7);
    CHECK(!m.owner().has_value());
    CHECK(m.tryWait(9) == Wait::Abandoned);
    CHECK_EQ(m.owner().value_or(0), 9);
    m.release(9);
    CHECK(m.tryWait(10) == Wait::Acquired);
}
TEST("semaphores count") {
    Semaphore s{ 2, 3 };
    CHECK(s.tryWait()); CHECK(s.tryWait());
    CHECK(!s.tryWait());
    CHECK(s.release(3));
    CHECK_EQ(s.count(), 3);
    CHECK(!s.release(1));
    CHECK_EQ(s.count(), 3);
    CHECK(!s.release(0));
}

